//! Multisig addresses against embit (the library of SeedSigner, Krux and
//! Specter DIY), as an outside oracle: fixed vectors generated by
//! tools/gen_embit_vectors.py. Together with rust-miniscript (multisig.rs)
//! and the BIP vectors, three independent implementations must agree with
//! Bitpunk, so no single one becomes the reference.

#[path = "data/embit_multisig.rs"]
mod embit;

use bp_bitcoin::multisig::descriptor::{self, Form};
use bp_bitcoin::Network;

#[test]
fn addresses_and_descriptors_match_embit() {
    assert_eq!(embit::VECTORS.len(), 8);
    for (desc, net, receive, change) in embit::VECTORS {
        let net = match *net {
            "main" => Network::Mainnet,
            _ => Network::Testnet,
        };
        // embit's checksum is ours
        let p = descriptor::parse(desc).unwrap_or_else(|e| panic!("{e:?}: {desc}"));
        assert!(p.had_checksum);
        let w = p.wallet;
        // writing it back gives embit's text exactly (order, `h`, checksum)
        let mut out = [0u8; descriptor::MAX_DESCRIPTOR];
        let n = descriptor::write(&w, Form::Multipath, &mut out).unwrap();
        assert_eq!(std::str::from_utf8(&out[..n]).unwrap(), *desc);
        for (branch, want) in [(0u32, receive), (1, change)] {
            let br = w.branch(branch).unwrap();
            for (&i, a) in embit::INDEXES.iter().zip(want.iter()) {
                let mut buf = [0u8; 90];
                let len = br.derive(i).unwrap().address(net, &mut buf);
                assert_eq!(
                    std::str::from_utf8(&buf[..len]).unwrap(),
                    *a,
                    "{desc} {branch}/{i}"
                );
            }
        }
    }
}
